import json
from datetime import date

_DATA = json.loads(r'''[{"date":"2026-10-26","chapter":1,"title":"Почему ночью темно?","body":"Кажется, глупый вопрос: потому что Солнце зашло! 😄 А вот учёные задумались серьёзнее: если звёзд бесконечно много и они светили вечно, отчего всё небо не сияет?\n\nОдна из разгадок в том, что у Вселенной есть история, а свет путешествует не мгновенно. Он ещё не успел принести нам сияние из всех далёких уголков.\n\nПредставляете, даже темнота может рассказать о времени!\n\nА когда вы в последний раз любовались ночным небом?"},{"date":"2026-10-27","chapter":2,"title":"Восемь минут назад","body":"Утренний солнечный луч — настоящий путешественник во времени. Прежде чем согреть нашу ладонь, он летел от Солнца около восьми минут.\n\nПолучается, мы видим Солнце не таким, какое оно в эту секунду, а таким, каким оно было чуть раньше. Космос словно присылает новости с задержкой. И без кнопки «обновить»! ☀️\n\nА в нашей жизни тоже есть мгновения, которые нельзя отложить до следующего обновления.\n\nЧто вам хочется заметить именно сегодня?"},{"date":"2026-10-28","chapter":1,"title":"Черепахи и уверенность","body":"Когда-то мир объясняли очень просто: Земля стоит на черепахе. А та — на другой. И так далее, пока у черепах не закончатся выходные. 🐢\n\nСтивен Хокинг начал разговор о Вселенной с этой забавной истории. Она напоминает: уверенность в ответе ещё не делает ответ верным.\n\nИногда одно хорошее «почему?» открывает больше, чем сотня привычных «так было всегда».\n\nА какое убеждение вы однажды пересмотрели — и обрадовались этому?"},{"date":"2026-10-29","chapter":9,"title":"Чашка, которая не возвращается","body":"Если чашка упала и разбилась, её осколки не соберутся сами и не запрыгнут обратно на стол. Хотя для домашнего хозяйства это было бы прекрасным открытием! ☕\n\nХокинг объяснял на таком примере направление времени: некоторые процессы в обычном мире необратимы.\n\nМы тоже не можем вернуть вчерашний вечер. Зато можем иначе прожить сегодняшний.\n\nА какой обычный момент вы теперь стараетесь не пропускать?"},{"date":"2026-10-30","chapter":8,"title":"Немного звёзд внутри нас","body":"Оказывается, у нас со звёздами больше общего, чем кажется. Многие химические элементы, из которых состоит наше тело, возникли в недрах предыдущих поколений звёзд.\n\nДолгая космическая история — и вот мы сидим за столом, пьём чай и переживаем из-за списка дел.\n\nНевероятно: природа потратила миллиарды лет, чтобы мы могли прожить этот день. А мы иногда не находим десяти минут для того, что любим.\n\nЧто сегодня стоит этих десяти минут?"},{"date":"2026-10-31","chapter":9,"title":"Память не бесплатна","body":"Даже память требует энергии. Хокинг объяснял это на примере компьютера: чтобы сохранить информацию, машине нужно потратить энергию и выделить тепло.\n\nА у нас в голове порой открыто столько «вкладок», что компьютер позавидует. 😄\n\nМожет, не каждую мелочь обязательно держать в памяти? Расписания, напоминания, повторяющиеся дела можно доверить цифровым помощникам, а себе оставить пространство для мыслей и разговоров.\n\nКакую заботу вы с радостью сняли бы со своей головы?"},{"date":"2026-11-01","chapter":3,"title":"Письмо длиной в четыре года","body":"От ближайшей к Солнцу звезды — Проксимы Центавра — свет идёт до нас более четырёх лет.\n\nПредставьте: когда-то он отправился в путь, а вы за это время успели встретить людей, отпраздновать дни рождения, изменить планы и, может быть, сами измениться.\n\nМы смотрим на крошечную точку в небе, а видим далёкое прошлое. Вселенная хранит удивительные письма, которые идут годами.\n\nКакое событие последних четырёх лет изменило вас сильнее всего?"},{"date":"2026-11-02","chapter":2,"title":"Перо против тяжёлого груза","body":"Долгое время считалось: тяжёлое обязано падать быстрее лёгкого. А Галилей решил не спорить бесконечно, а проверить.\n\nОказалось, в отсутствие сопротивления воздуха разные тела падают одинаково. Позже на Луне астронавт продемонстрировал это с пером и молотком.\n\nКакая прекрасная привычка — проверять то, что всем кажется очевидным!\n\nИнтересно, сколько времени мы тратим на убеждения, которые ни разу не испытали на практике?\n\nЧто вам когда-нибудь помогло изменить мнение?"},{"date":"2026-11-03","chapter":2,"title":"Часы на горе","body":"Представьте два очень точных часа. Одни стоят у подножия горы, другие — высоко наверху. Они будут идти чуть по-разному!\n\nЭто не каприз механизма: согласно теории относительности, гравитация влияет на ход времени. Разницу приходится учитывать даже в спутниковой навигации.\n\nУдивительно: точность маршрута зависит от того, как мы понимаем время.\n\nА вот маршрута к собственной радости никакой навигатор за нас не построит.\n\nКуда вы давно хотите отправиться, пусть даже пешком?"},{"date":"2026-11-04","chapter":3,"title":"Вселенная как воздушный шар","body":"Нарисуйте на воздушном шарике несколько точек и начните его надувать. Точки будут удаляться друг от друга, хотя ни одна не обязана быть центром всей истории.\n\nТак Хокинг объяснял расширение Вселенной. Галактики не просто разлетаются в пустоте: увеличиваются расстояния между ними.\n\nМне нравится эта картина. Мир оказывается намного больше привычной комнаты и привычных забот.\n\nА когда вам в последний раз удалось взглянуть на свою жизнь шире?"},{"date":"2026-11-05","chapter":3,"title":"Голуби и рождение Вселенной","body":"Два учёных пытались избавиться от странного шума в антенне. Проверили оборудование, заглянули внутрь — даже следы голубей убрали. А шум остался.\n\nВ итоге оказалось: прибор улавливал слабое излучение, сохранившееся от ранней Вселенной!\n\nВот уж находка: искали помеху, а наткнулись на космическую историю. 🐦\n\nИногда неожиданность — не препятствие, а приглашение присмотреться.\n\nА вам случалось обнаружить что-то хорошее там, где сначала была одна досада?"},{"date":"2026-11-06","chapter":4,"title":"Физика мыльного пузыря","body":"Радужные переливы мыльного пузыря — не просто красивая случайность. Световые волны, отражаясь от тонкой плёнки, то усиливают, то ослабляют друг друга.\n\nЗа детской забавой прячется серьёзная физика. И это прекрасно: мир не требует диплома, чтобы удивлять нас.\n\nИногда мы проходим мимо маленького чуда, потому что спешим к какому-то большому делу.\n\nА какая самая простая вещь недавно вызвала у вас улыбку?"},{"date":"2026-11-07","chapter":5,"title":"Атом оказался не точкой","body":"Когда-то атом называли неделимым. Название такое уверенное, что даже неловко было спорить.\n\nНо учёные заглянули глубже — и обнаружили электроны, ядро, а позднее и кварки. Мир оказался устроен гораздо интереснее, чем предполагали.\n\nМне нравится эта история: иногда то, что мы считаем пределом, оказывается лишь дверью в следующую комнату.\n\nА что нового вы хотели бы попробовать, если бы перестали говорить себе «поздно начинать»?"},{"date":"2026-11-08","chapter":5,"title":"Не пожимайте руку двойнику","body":"Хокинг с юмором предупреждал: если встретите точную копию себя из антивещества, не спешите здороваться за руку! Частица и соответствующая античастица способны уничтожить друг друга, превратив энергию в другие частицы.\n\nК счастью, на соседней улице антимиров пока не обнаружили. 😄\n\nНо мысль любопытная: внешнее сходство ещё ничего не говорит о том, что скрыто внутри.\n\nА бывало у вас, что человек удивлял вас совсем не той стороной, которую вы ожидали увидеть?"},{"date":"2026-11-09","chapter":6,"title":"Почему большие звёзды торопятся","body":"Странный космический парадокс: очень массивные звёзды расходуют своё топливо быстрее, чем звёзды поменьше. Их сияние бывает ослепительным, зато жизнь — короче.\n\nВыходит, даже звезде не всегда на пользу гореть на пределе возможностей.\n\nУ человека, конечно, совсем другая физика. Но сравнение забавное: как часто мы стараемся сиять на работе так ярко, что на вечер уже не остаётся сил?\n\nЧто помогает вам восстанавливать свою энергию?"},{"date":"2026-11-10","chapter":7,"title":"Чёрная дыра не совсем чёрная","body":"Название обещает абсолютную темноту. Но Стивен Хокинг показал: квантовая теория предсказывает, что чёрные дыры должны испускать слабое излучение.\n\nПредставляете, даже «самая чёрная» вещь во Вселенной оказалась не такой уж однозначной!\n\nИменно поэтому мне нравятся вопросы: они спасают нас от привычки приклеивать ярлык и считать, будто всё понятно.\n\nА какая вещь или человек неожиданно открылись вам с другой стороны?"},{"date":"2026-11-11","chapter":9,"title":"Хокинг признал ошибку","body":"Стивен Хокинг однажды пришёл к выводу, что при сжатии Вселенной время могло бы словно повернуть вспять. Позже коллеги указали на проблему, и он признал: вывод был ошибочным.\n\nДаже великий учёный сказал по сути: «Я передумал».\n\nИ ничего страшного — Вселенная от этого не развалилась! 😄\n\nМожет быть, умение менять мнение — признак не слабости, а настоящей свободы мысли?\n\nКогда вам в последний раз было приятно признать: «Теперь я вижу иначе»?"},{"date":"2026-11-12","chapter":1,"title":"Одна точная проверка","body":"В науке можно годами любоваться стройной теорией. А потом появляется одно наблюдение, которое заставляет её пересмотреть.\n\nХокинг напоминал: хорошая теория должна не только красиво объяснять прошлое, но и позволять проверять предсказания.\n\nИногда и в жизни полезно спросить: «Это правда работает — или я просто привык так делать?»\n\nОсобенно когда речь о делах, на которые ежедневно уходят часы.\n\nЕсть ли у вас привычка, которую давно хочется проверить на полезность?"},{"date":"2026-11-13","chapter":8,"title":"А что было до начала?","body":"Мы привыкли спрашивать: что было раньше? Вчера — позавчера, а до позавчера — ещё день.\n\nНо если само время связано с историей Вселенной, вопрос «что было до её начала?» оказывается куда сложнее, чем кажется.\n\nХокинг исследовал разные модели, включая предположение, что у пространства-времени может вообще не быть края.\n\nКакое удивительное слово — «начало». Оно кажется простым, пока не начинаешь думать.\n\nА что в вашей жизни началось совершенно неожиданно?"},{"date":"2026-11-14","chapter":8,"title":"Край света отменяется","body":"Представьте, что идёте по Земле всё время в одном направлении. Рано или поздно можно вернуться к исходной точке — но ни с какого края вы не упадёте.\n\nХокинг использовал похожий образ для гипотезы о Вселенной: она может быть конечной, но не иметь границ.\n\nЭто именно гипотеза, а не готовый ответ на все вопросы.\n\nМне нравится, как природа заставляет усомниться в самом слове «край».\n\nА где вам хотелось бы выйти за границы привычного?"},{"date":"2026-11-15","chapter":3,"title":"Мы не центр Вселенной","body":"Глядя на небо, можно решить, будто все далёкие галактики удаляются именно от нас. Ну конечно, мы же здесь главные! 😄\n\nНо расширение пространства можно наблюдать из разных галактик. Нам не обязательно занимать особое центральное место.\n\nХорошее напоминание: мир гораздо больше нашего окна, нашего города и даже нашей точки зрения.\n\nА какую интересную мысль вам подарил человек, смотрящий на жизнь совсем иначе?"},{"date":"2026-11-16","chapter":4,"title":"Будущее не по расписанию","body":"Когда-то учёные мечтали: узнаем все законы природы — и сможем вычислить будущее до последней мелочи.\n\nКвантовая механика разрушила эту мечту об абсолютной предсказуемости. Для некоторых процессов она позволяет рассчитать вероятности, но не гарантирует один-единственный исход.\n\nИ знаете, в этом есть особенная прелесть: завтрашний день ещё способен нас удивить.\n\nА что вы хотели бы однажды сделать спонтанно, без подробного плана?"},{"date":"2026-11-17","chapter":2,"title":"Кто здесь движется?","body":"Пассажир поезда сидит спокойно и читает книгу. Для человека на платформе он мчится вместе с вагоном.\n\nТак кто движется, а кто стоит? Всё зависит от того, относительно чего мы измеряем движение.\n\nХокинг показывает: в физике нет одного волшебного указателя «абсолютный покой».\n\nА в жизни иногда полезно сменить точку зрения. Особенно если кажется, что все вокруг несутся, а ты отстаёшь.\n\nКогда взгляд со стороны помог вам перестать спешить?"},{"date":"2026-11-18","chapter":6,"title":"Граница, за которой молчание","body":"У чёрной дыры есть необычная граница — горизонт событий. Если свет пересёк её внутрь, выбраться наружу он уже не сможет.\n\nЗвучит как космическая дверь без ручки. 🚪\n\nРазумеется, наши домашние двери устроены дружелюбнее. И всё же меня зацепило сравнение: бывают мгновения, после которых вернуть сказанное или несделанное уже нельзя.\n\nКакое доброе слово вам хочется сказать сегодня, не откладывая?"},{"date":"2026-11-19","chapter":9,"title":"Почему пазл не собирается сам","body":"Если встряхнуть коробку с собранным пазлом, картинка, скорее всего, рассыплется. А вот чтобы детали сами сложились обратно, понадобилось бы невероятное совпадение.\n\nТак Хокинг иллюстрировал рост беспорядка — одну из стрел времени.\n\nИ ведь с рабочим столом происходит похожее: порядок редко появляется от одного взгляда. 😄\n\nМожет, стоит освобождать время не от всего подряд, а от повторяющихся мелочей?\n\nКакую ежедневную мелочь вы с удовольствием автоматизировали бы?"},{"date":"2026-11-20","chapter":5,"title":"Самая слабая сила","body":"Гравитация — самая слабая из четырёх фундаментальных сил природы. Но она действует на огромных расстояниях и собирает целые звёзды и галактики.\n\nПарадокс! То, что кажется слабым, способно определять судьбы гигантов.\n\nВ жизни тоже не всё важное шумит и требует немедленного внимания. Иногда тихий разговор или короткая прогулка меняют настроение сильнее большой победы.\n\nА какая маленькая вещь оказывает на вас неожиданно большое влияние?"},{"date":"2026-11-21","chapter":4,"title":"Один электрон — два пути?","body":"В знаменитом опыте с двумя щелями электроны образуют узор, похожий на след волны. Причём удивительная картина возникает даже тогда, когда электроны запускают по одному.\n\nКвантовый мир словно говорит: «Не спешите представлять меня обычными шариками!»\n\nМне нравится, что в природе есть место настоящему удивлению, а не только готовым ответам.\n\nА какой вопрос вы бы задали учёному, если бы он обещал ответить без сложных формул?"},{"date":"2026-11-22","chapter":5,"title":"Почему мы вообще здесь","body":"В ранней Вселенной возникали частицы и античастицы. Если бы вещества и антивещества осталось поровну, привычного мира со звёздами и планетами могло бы не появиться.\n\nНо вещество сохранилось — и теперь мы можем смотреть на небо, пить чай и смеяться над шутками.\n\nКажется, обычное воскресное утро становится чуточку удивительнее, если помнить, насколько необычна сама возможность жить.\n\nА за какую простую радость вы благодарны сегодняшнему дню?"},{"date":"2026-11-23","chapter":3,"title":"Невидимое тоже действует","body":"Учёные заметили: звёзды в галактиках движутся так, будто там есть больше вещества, чем мы видим. Так возникла одна из линий доказательств существования тёмной материи.\n\nНельзя увидеть её глазами — но можно заметить последствия её притяжения.\n\nСколько важного в жизни мы тоже узнаём не по внешнему блеску, а по результатам: забота, внимание, надёжность.\n\nПо каким маленьким поступкам вы понимаете, что человеку можно доверять?"},{"date":"2026-11-24","chapter":10,"title":"Туннель сквозь космос","body":"Представьте лист бумаги с двумя далёкими точками. Если его согнуть, точки окажутся ближе. Похожую идею физики обсуждают, рассуждая о кротовых норах — гипотетических туннелях в пространстве-времени.\n\nПостроить такой проход мы пока не умеем. Поэтому поездку к соседней звезде лучше не планировать на выходные. 😄\n\nА вот в повседневной жизни короткие пути существуют: иногда один удачный инструмент освобождает целый вечер.\n\nГде вам больше всего хочется найти такой путь?"},{"date":"2026-11-25","chapter":10,"title":"Где туристы из будущего?","body":"Хокинг задавал замечательно озорной вопрос: если путешествовать в прошлое возможно, почему нас ещё не окружили туристы из будущего?\n\nПредставляете экскурсовода: «Слева — XXI век, справа — очередь в супермаркете»! 😄\n\nУчёные пока не доказали, что машину времени можно построить. Зато сегодняшний день у нас уже есть, и билет покупать не требуется.\n\nЕсли бы гость из будущего спросил, чем прекрасна наша эпоха, что бы вы ему ответили?"},{"date":"2026-11-26","chapter":11,"title":"Миру не хватает одной карты","body":"Хокинг сравнивал поиски единой теории с составлением географических карт. Всю поверхность Земли нельзя без искажений изобразить на одной плоской карте — приходится использовать несколько.\n\nКак похоже на жизнь! Для работы полезен один способ мышления, для дружбы — другой, для отдыха — третий.\n\nИ необязательно самому делать всё. Иногда разумнее передать однообразные дела помощникам, в том числе цифровым, и оставить силы на то, что умеет только человек.\n\nЧто бы вы оставили исключительно себе?"},{"date":"2026-11-27","chapter":11,"title":"Соломинка и лишние измерения","body":"Издалека соломинка кажется тонкой линией. Но муравей, ползущий по её поверхности, мог бы двигаться и вдоль, и вокруг неё.\n\nХокинг использовал такой образ, объясняя гипотезы о дополнительных измерениях пространства. Их существование в подобных теориях ещё не означает, что мы их обнаружили.\n\nПоразительно: иногда мир оказывается сложнее лишь потому, что мы смотрим слишком издалека.\n\nА к чему вам давно хочется присмотреться повнимательнее?"},{"date":"2026-11-28","chapter":12,"title":"Солнце работает по законам","body":"Люди когда-то пытались задобрить силы природы, чтобы Солнце взошло. А потом заметили: оно поднимается над горизонтом и без уговоров.\n\nТак постепенно рождалась наука — из наблюдений за тем, что повторяется и поддаётся объяснению.\n\nМне нравится это спокойное доверие к проверенным вещам. И немного завидую Солнцу: у него нет списка сообщений, на которые надо срочно ответить. ☀️\n\nА какая простая утренняя привычка помогает вам начать день?"},{"date":"2026-11-29","chapter":12,"title":"Галилей и право спросить","body":"Галилей не просто предлагал новую картину мира. Он настаивал: наблюдения важнее привычного авторитета.\n\nЗа свои взгляды он столкнулся с тяжёлыми последствиями. Но вопросы, которые он помог поставить перед наукой, остались с человечеством.\n\nМы сегодня можем смотреть в небо и спокойно спрашивать: «Почему так?» Это огромная свобода.\n\nА какой вопрос вы давно хотели задать, но всё не решались?"},{"date":"2026-11-30","chapter":12,"title":"Для чего нам всё это время?","body":"Хокинг завершает путешествие по загадкам Вселенной вопросом куда больше любой формулы: почему существует мир — и почему в нём есть мы?\n\nЗа этот месяц мы заглядывали в прошлое звёзд, искали стрелу времени и даже заглядывали к чёрным дырам. А самое близкое чудо, возможно, всё это время было рядом: возможность проживать свои дни осмысленно.\n\nДеньги можно снова заработать. Рутинную работу всё чаще можно поручить технологиям. А собственную жизнь никому не передашь.\n\nКакое мгновение ноября вы хотели бы унести с собой в декабрь?"}]''')
CALENDAR = {date.fromisoformat(row["date"]): row for row in _DATA}
FIRST_EDITORIAL_DAY = date(2026, 10, 26)
LAST_EDITORIAL_DAY = date(2026, 11, 30)
assert len(CALENDAR) == 36


def get_entry(day):
    return CALENDAR.get(day)


def compose_entry(day):
    item = get_entry(day)
    if not item:
        return None
    return ("☀️ Доброе утро, друзья!\n💭 МЫСЛИ ВСЛУХ | ВРЕМЯ\n\n"
            + item["body"] + "\n\nВаша Ора 💛")


def upcoming(day, count=7):
    return [row for row in _DATA if row["date"] >= day.isoformat()][:count]
